using HotChocolate.Authorization;
using GraphApi.Infrastructure.Services;using GraphApi.Models.ENC.TiposPregunta;using GraphApi.Services.ENC.TiposPregunta;using HotChocolate;using System.Linq;namespace GraphApi.GraphQL.ENC.TiposPregunta{    [MutationType]    [GraphQLDescription("Punto de entrada para las mutaciones de TiposPreguntas: creación, actualización y eliminación.")]    public class TiposPreguntaMutation    {        [Authorize]        [GraphQLName("createTiposPregunta")]        [GraphQLDescription("Crea un nuevo TiposPregunta usando los headers 'UserID' y 'WindowName'.")]        public async Task<clReadTiposPregunta> CreateTiposPreguntaAsync(            [GraphQLDescription("Datos necesarios para crear el TiposPregunta.")]            clCreateTiposPregunta objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de TiposPregunta.")]            ITiposPreguntaService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.CreateTiposPregunta(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("updateTiposPregunta")]        [GraphQLDescription("Actualiza los campos especificados de un TiposPregunta existente.")]        public async Task<clReadTiposPregunta?> UpdateTiposPreguntaAsync(            [GraphQLDescription("Datos del TiposPregunta a actualizar.")]            clUpdateTiposPregunta objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de TiposPregunta.")]            ITiposPreguntaService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.UpdateTiposPregunta(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("deleteTiposPregunta")]        [GraphQLDescription("Elimina un TiposPregunta por su ID.")]        public async Task<bool> delTiposPreguntaAsync(            [GraphQLDescription("ID del TiposPregunta a eliminar.")]            int nTiposPreguntaID,            [Service]            [GraphQLDescription("Servicio para operaciones de TiposPregunta.")]            ITiposPreguntaService objService        )        {            return await objService.DeleteTiposPregunta(nTiposPreguntaID);        }    }}